/* Trust Electronics — site interactions */
(function () {
  "use strict";

  var reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ---- Brand mark: recolor the logo to light blue on a transparent background ---- */
  var TE_LOGO_SRC = window.TE_LOGO || "data:image/jpeg;base64,";
  (function tintBrandLogo() {
    if (!TE_LOGO_SRC) return;
    var img = new Image();
    img.onload = function () {
      try {
        var c = document.createElement("canvas"); c.width = img.naturalWidth; c.height = img.naturalHeight;
        var cx = c.getContext("2d"); cx.drawImage(img, 0, 0);
        var d = cx.getImageData(0, 0, c.width, c.height), p = d.data;
        for (var i = 0; i < p.length; i += 4) {
          if (p[i] < 60 && p[i + 1] < 60 && p[i + 2] < 60) { p[i + 3] = 0; }      // black bg -> transparent, original colors kept
        }
        cx.putImageData(d, 0, 0);
        document.documentElement.style.setProperty("--te-brand", "url(" + c.toDataURL("image/png") + ")");
      } catch (e) {}
    };
    img.src = TE_LOGO_SRC;
  })();

  /* ---- Intro / Welcome animation (logo drops, then WELCOME, then name) ---- */
  var intro = document.getElementById("intro");
  if (intro) {
    var seen = false;
    try { seen = sessionStorage.getItem("te_intro") === "1"; } catch (e) {}

    if (seen) {
      // Shown once this session already — remove without replaying
      intro.parentNode && intro.parentNode.removeChild(intro);
    } else {
      try { sessionStorage.setItem("te_intro", "1"); } catch (e) {}
      /* intro overlay disabled — opening is part of the scroll journey now */
      var closed = false;
      var closeIntro = function () {
        if (closed) return; closed = true;
        intro.classList.add("hide");
        document.body.classList.remove("intro-active");
        setTimeout(function () { intro.parentNode && intro.parentNode.removeChild(intro); }, 950);
      };
      var startPlay = function () { intro.classList.add("play"); };

      // Knock out the logo's black background at runtime -> clean transparent logo
      var TE_LOGO = window.TE_LOGO || "";
      if (TE_LOGO) {
        var limg = new Image();
        limg.onload = function () {
          try {
            var c = document.createElement("canvas"); c.width = limg.naturalWidth; c.height = limg.naturalHeight;
            var cx = c.getContext("2d"); cx.drawImage(limg, 0, 0);
            var d = cx.getImageData(0, 0, c.width, c.height), p = d.data;
            for (var i = 0; i < p.length; i += 4) { if (p[i] < 60 && p[i + 1] < 60 && p[i + 2] < 60) p[i + 3] = 0; }
            cx.putImageData(d, 0, 0);
            document.documentElement.style.setProperty("--te-logo", "url(" + c.toDataURL("image/png") + ")");
          } catch (e) { document.documentElement.style.setProperty("--te-logo", "url(" + TE_LOGO + ")"); }
          startPlay();
        };
        limg.onerror = function () { document.documentElement.style.setProperty("--te-logo", "url(" + TE_LOGO + ")"); startPlay(); };
        limg.src = TE_LOGO;
      } else { startPlay(); }

      var skip = intro.querySelector(".intro__skip");
      if (skip) skip.addEventListener("click", closeIntro);
      intro.addEventListener("click", function (e) { if (e.target === intro) closeIntro(); });
      document.addEventListener("keydown", function (e) { if (e.key === "Escape") closeIntro(); });
      setTimeout(closeIntro, reduceMotion ? 1400 : 4400);
    }
  }

  /* ---- Animated number-free stat pop ---- */
  var statEls = document.querySelectorAll(".stat b");
  if ("IntersectionObserver" in window && statEls.length && !reduceMotion) {
    var so = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) {
          en.target.animate(
            [{ transform: "translateY(10px)", opacity: 0 }, { transform: "none", opacity: 1 }],
            { duration: 600, easing: "cubic-bezier(.2,.8,.2,1)", fill: "both" }
          );
          so.unobserve(en.target);
        }
      });
    }, { threshold: 0.4 });
    statEls.forEach(function (el) { so.observe(el); });
  }

  /* ---- Subtle 3D tilt on cards ---- */
  if (!reduceMotion && window.matchMedia("(hover:hover)").matches) {
    document.querySelectorAll(".card").forEach(function (card) {
      card.addEventListener("mousemove", function (e) {
        var r = card.getBoundingClientRect();
        var px = (e.clientX - r.left) / r.width - 0.5;
        var py = (e.clientY - r.top) / r.height - 0.5;
        card.style.transform = "perspective(760px) rotateX(" + (-py * 9) + "deg) rotateY(" + (px * 10) + "deg) translateY(-10px) scale(1.02)";
      });
      card.addEventListener("mouseleave", function () { card.style.transform = ""; });
    });
  }

  /* Mobile navigation toggle */
  var toggle = document.querySelector(".nav-toggle");
  var links = document.querySelector(".nav-links");
  if (toggle && links) {
    toggle.addEventListener("click", function () {
      var open = links.classList.toggle("open");
      toggle.classList.toggle("open", open);
      toggle.setAttribute("aria-expanded", open ? "true" : "false");
    });
    links.querySelectorAll("a").forEach(function (a) {
      a.addEventListener("click", function () {
        links.classList.remove("open");
        toggle.classList.remove("open");
        toggle.setAttribute("aria-expanded", "false");
      });
    });
  }

  /* Reveal-on-scroll animation with staggering */
  // Tag granular items so they animate individually.
  document.querySelectorAll(".checklist li, .info-item, .footer-grid > *").forEach(function (el) { el.classList.add("reveal"); });

  // Give items inside a group an incremental delay -> they appear one by one.
  document.querySelectorAll(".grid, .stats, .checklist, .footer-grid").forEach(function (group) {
    var i = 0;
    Array.prototype.forEach.call(group.children, function (child) {
      if (child.classList.contains("reveal")) {
        child.style.transitionDelay = Math.min(i * 80, 640) + "ms"; // capped so a group finishes well under 1.5s
        i++;
      }
    });
  });

  var reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window && reveals.length) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
      });
    }, { threshold: 0.12, rootMargin: "0px 0px -8% 0px" });
    reveals.forEach(function (el) { io.observe(el); });
  } else {
    reveals.forEach(function (el) { el.classList.add("in"); });
  }

  /* Staggered list items on service / product pages (each line appears one after another) */
  var staggerLists = document.querySelectorAll(".svc ul, .svc ol, .svc-page ul, .svc-page ol");
  if (staggerLists.length && "IntersectionObserver" in window) {
    staggerLists.forEach(function (ul) {
      Array.prototype.forEach.call(ul.children, function (li, i) {
        if (li.tagName !== "LI") return;
        li.classList.add("li-stagger");
        li.style.transitionDelay = Math.min(i * 70, 700) + "ms";
      });
    });
    var lio = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add("in"); lio.unobserve(e.target); } });
    }, { threshold: 0.1, rootMargin: "0px 0px -6% 0px" });
    document.querySelectorAll(".li-stagger").forEach(function (li) { lio.observe(li); });
  }

  /* Highlight the current page in the nav so visitors can see where they are */
  (function () {
    var path = (location.pathname.split("/").pop() || "index.html").toLowerCase();
    var svc = ["services.html","software.html","hardware.html","turnkey.html","asic.html","mechanical.html","rf.html","npi.html"];
    var prod = ["products.html","lidar.html","rfid.html","uriel.html","bg930.html","led.html"];
    document.querySelectorAll(".nav-links > li > a").forEach(function (a) {
      if ((a.getAttribute("href") || "").toLowerCase() === path) a.classList.add("active");
    });
    document.querySelectorAll(".nav-links .has-drop > a").forEach(function (a) {
      var href = (a.getAttribute("href") || "").toLowerCase();
      if ((href === "services.html" && svc.indexOf(path) >= 0) || (href === "products.html" && prod.indexOf(path) >= 0))
        a.classList.add("active");
    });
  })();

  /* Current year in footer */
  var y = document.querySelectorAll("[data-year]");
  y.forEach(function (el) { el.textContent = new Date().getFullYear(); });

  /* Contact form — front-end validation + graceful demo submit.
     Wire the `action` attribute to your mail handler / form service to go live. */
  // ===== Contact / newsletter forms via Web3Forms =====
  // 1) Get a free access key at https://web3forms.com  (enter tali@trust-electronics.com)
  // 2) Paste it below, replacing REPLACE_WITH_YOUR_ACCESS_KEY. That's it — messages arrive by email.
  var WEB3FORMS_KEY = "REPLACE_WITH_YOUR_ACCESS_KEY";

  document.querySelectorAll("form[data-contact]").forEach(function (form) {
    var status = form.querySelector(".form-status");
    var btn = form.querySelector('button[type="submit"]');
    function say(msg, color) { if (status) { status.textContent = msg; status.style.color = color || "#0e8ba3"; } }

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      if (!form.checkValidity()) { form.reportValidity(); return; }

      // Not configured yet → keep the friendly demo behaviour
      if (!WEB3FORMS_KEY || WEB3FORMS_KEY === "REPLACE_WITH_YOUR_ACCESS_KEY") {
        say("Our online form is still being set up — meanwhile please email tali@trust-electronics.com or call +972-3-6322566.", "#0e8ba3");
        return;
      }

      var data = new FormData(form);
      data.append("access_key", WEB3FORMS_KEY);
      if (!data.get("subject")) data.append("subject", "New enquiry from the Trust Electronics website");
      data.append("from_name", "Trust Electronics website");

      say("Sending…", "#7a8794");
      if (btn) btn.disabled = true;

      fetch("https://api.web3forms.com/submit", {
        method: "POST", headers: { "Accept": "application/json" }, body: data
      })
        .then(function (r) { return r.json(); })
        .then(function (json) {
          if (json.success) { say("Thank you! Your message has been sent.", "#0e8ba3"); form.reset(); }
          else { say("Sorry, something went wrong: " + (json.message || "please try again."), "#b23434"); }
        })
        .catch(function () { say("Network error — please try again, or email us directly.", "#b23434"); })
        .then(function () { if (btn) btn.disabled = false; });
    });
  });

  /* ---------- Accessibility toolbar ---------- */
  (function buildA11y() {
    var root = document.documentElement;
    var store = {
      get: function (k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
      set: function (k, v) { try { localStorage.setItem(k, v); } catch (e) {} },
      del: function (k) { try { localStorage.removeItem(k); } catch (e) {} }
    };

    // Skip-to-content link
    var skip = document.createElement("a");
    skip.className = "skip-link"; skip.textContent = "Skip to main content";
    document.body.insertBefore(skip, document.body.firstChild);
    var mainEl = document.querySelector(".hero") || document.querySelector("section") || document.body;
    if (!mainEl.id) mainEl.id = "te-main";
    skip.setAttribute("href", "#" + mainEl.id);
    mainEl.setAttribute("tabindex", "-1");

    // Persisted text-size level
    var fontLevels = [100, 110, 125, 140], fontIdx = parseInt(store.get("te_font") || "0", 10) || 0;
    function applyFont() { root.style.fontSize = fontLevels[fontIdx] + "%"; }
    applyFont();

    var toggles = { contrast: "a11y-contrast", links: "a11y-links", readable: "a11y-readable", grayscale: "a11y-grayscale" };
    Object.keys(toggles).forEach(function (k) { if (store.get("te_" + k) === "1") root.classList.add(toggles[k]); });

    var btn = document.createElement("button");
    btn.className = "a11y-btn"; btn.type = "button";
    btn.setAttribute("aria-label", "Accessibility options"); btn.setAttribute("aria-expanded", "false");
    btn.innerHTML = '<svg width="26" height="26" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="4" r="2" fill="currentColor"/><path d="M4 8h16M12 8v6m0 0-3 6m3-6 3 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

    var panel = document.createElement("div");
    panel.className = "a11y-panel"; panel.setAttribute("role", "dialog"); panel.setAttribute("aria-label", "Accessibility toolbar");
    panel.innerHTML =
      '<h4>Accessibility</h4><div class="row">' +
      '<button data-act="font-inc">A+ Bigger text</button>' +
      '<button data-act="font-dec">A&minus; Smaller text</button>' +
      '<button data-act="contrast">High contrast</button>' +
      '<button data-act="links">Highlight links</button>' +
      '<button data-act="readable">Readable font</button>' +
      '<button data-act="grayscale">Grayscale</button>' +
      '<button class="a11y-reset" data-act="reset">Reset all</button>' +
      '</div><a class="statement" href="accessibility.html">Accessibility statement</a>';

    document.body.appendChild(btn); document.body.appendChild(panel);

    function sync() {
      panel.querySelectorAll("button[data-act]").forEach(function (b) {
        var a = b.getAttribute("data-act");
        if (toggles[a]) b.classList.toggle("on", root.classList.contains(toggles[a]));
      });
    }
    sync();

    btn.addEventListener("click", function () {
      var open = panel.classList.toggle("open");
      btn.setAttribute("aria-expanded", open ? "true" : "false");
    });
    panel.addEventListener("click", function (e) {
      var b = e.target.closest("button[data-act]"); if (!b) return;
      var act = b.getAttribute("data-act");
      if (act === "font-inc") { fontIdx = Math.min(fontIdx + 1, fontLevels.length - 1); store.set("te_font", fontIdx); applyFont(); }
      else if (act === "font-dec") { fontIdx = Math.max(fontIdx - 1, 0); store.set("te_font", fontIdx); applyFont(); }
      else if (act === "reset") {
        fontIdx = 0; store.set("te_font", 0); applyFont();
        Object.keys(toggles).forEach(function (k) { root.classList.remove(toggles[k]); store.del("te_" + k); });
      } else if (toggles[act]) {
        var on = root.classList.toggle(toggles[act]); store.set("te_" + act, on ? "1" : "0");
      }
      sync();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") { panel.classList.remove("open"); btn.setAttribute("aria-expanded", "false"); }
    });
  })();

  /* ---------- Cookie consent banner ---------- */
  (function cookieBanner() {
    var ok; try { ok = localStorage.getItem("te_cookie"); } catch (e) { ok = null; }
    if (ok) return;
    var bar = document.createElement("div");
    bar.className = "cookie"; bar.setAttribute("role", "dialog"); bar.setAttribute("aria-label", "Cookie notice");
    bar.innerHTML = '<p>We use essential cookies to run this site. With your consent we may also use analytics cookies. See our <a href="privacy.html">Privacy Policy</a>.</p>' +
      '<div class="actions"><button class="btn decline" type="button">Essential only</button><button class="btn btn--primary" type="button">Accept</button></div>';
    document.body.appendChild(bar);
    function close(v) { try { localStorage.setItem("te_cookie", v); } catch (e) {} bar.parentNode && bar.parentNode.removeChild(bar); }
    bar.querySelector(".btn--primary").addEventListener("click", function () { close("all"); });
    bar.querySelector(".decline").addEventListener("click", function () { close("essential"); });
  })();

  /* ---------- Footer legal links ---------- */
  (function footerLinks() {
    var span = document.querySelector(".footer-bottom span:last-child");
    if (!span || span.innerHTML.indexOf("privacy.html") !== -1) return;
    span.innerHTML = '<a href="privacy.html">Privacy</a> · <a href="accessibility.html">Accessibility</a> · ' + span.innerHTML;
  })();

  /* ISO 9001 is reached from the footer (like the original site) — no top-nav item.
     The ISO reveal still opens from any iso.html link via the modal handler above. */

  /* ---------- ISO certificate reveal modal ---------- */
  (function isoModal() {
    var modal = document.createElement("div");
    modal.className = "iso-modal"; modal.id = "isoModal";
    modal.setAttribute("role", "dialog"); modal.setAttribute("aria-modal", "true");
    modal.setAttribute("aria-label", "ISO 9001:2015 certificates");
    modal.innerHTML =
      '<div class="iso-modal__inner">' +
        '<figure class="iso-cert iso-cert--en"><img src="assets/iso-english.jpg" alt="Trust Electronics ISO 9001:2015 certificate (English), No. I31680"></figure>' +
        '<figure class="iso-cert iso-cert--he"><img src="assets/iso-hebrew.jpg" alt="Trust Electronics ISO 9001:2015 certificate (Hebrew), No. I31680"></figure>' +
      '</div>' +
      '<button class="iso-modal__close" type="button" aria-label="Close">&times;</button>';
    document.body.appendChild(modal);

    var closeBtn = modal.querySelector(".iso-modal__close");
    function open() { modal.classList.add("open"); document.body.classList.add("iso-open"); }
    function close() { modal.classList.remove("open"); document.body.classList.remove("iso-open"); }

    closeBtn.addEventListener("click", close);
    modal.addEventListener("click", function (e) {
      if (e.target === modal || e.target.classList.contains("iso-modal__inner")) close();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && modal.classList.contains("open")) close();
    });
    // Any "ISO" link opens the animated reveal instead of navigating
    document.addEventListener("click", function (e) {
      var a = e.target.closest('a[href$="iso.html"]');
      if (a) { e.preventDefault(); open(); }
    });
  })();
})();
